(async()=>{
 const $=id=>document.getElementById(id);let selected=null,busy=false,done=false,sourceName='낙서 무기';
 const source=location.hash?Craft.readBattleWeapon(location.hash):null;
 if(source?.artwork){$('evolution-original').src=source.artwork;$('evolution-before').src=source.artwork;$('evolution-source-name').textContent=source.name;$('evolution-source-types').innerHTML=source.types.map(Craft.Types.badge).join('');$('evolution-grade').textContent=Craft.Rarity.get(source.rarity).label+' 등급 · 1차 진화';$('evolution-return').href='battle.html'+location.hash;}
 const reveal=EvolutionReveal.mount({stage:$('evolution-stage'),before:$('evolution-before'),after:$('evolution-after'),onComplete:()=>{busy=false;done=true;$('evolution-phase').textContent='진화했다!';$('evolution-stage-name').textContent=selected.name;$('evolution-stage-note').textContent=selected.line;$('evolution-message').textContent=sourceName+'이\n'+selected.name+'으로 진화했다!';$('evolution-confirm').disabled=false;$('evolution-confirm').textContent='다른 진화도 보기';$('evolution-confirm').focus({preventScroll:true});}});
 try{const r=await fetch('assets/studies/evolution/manifest.json');if(!r.ok)throw Error('진화형 이미지를 준비하고 있어.');const data=await r.json();
  // This isolated study has two genuinely generated examples for one drawing, not live generation.
  sourceName=data.sourceName;$('evolution-original').src=data.original;$('evolution-before').src=data.original;$('evolution-source-name').textContent=data.sourceName;$('evolution-source-types').innerHTML=data.sourceTypes.map(Craft.Types.badge).join('');$('evolution-grade').textContent=Craft.Rarity.get(data.rarity).label+' 등급 · 1차 진화';
  for(const option of data.options){const button=document.createElement('button');button.type='button';button.className='evolution-choice';button.style.setProperty('--evolution-type',Craft.Types.color(option.types[0]));button.setAttribute('aria-pressed','false');const image=document.createElement('img');image.src=option.image;image.alt=option.name+' 진화 외형';const content=document.createElement('div'),route=document.createElement('small'),name=document.createElement('strong'),types=document.createElement('div'),line=document.createElement('p');route.textContent=option.route;name.textContent=option.name;types.className='choice-types';types.innerHTML=option.types.map(Craft.Types.badge).join('');line.textContent=option.line;content.append(route,name,types,line);button.append(image,content);button.addEventListener('click',()=>{if(busy||done)return;selected=option;document.querySelectorAll('.evolution-choice').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('evolution-stage-name').textContent=option.name;$('evolution-stage-note').textContent=option.line;$('evolution-message').textContent=option.story;$('evolution-confirm').disabled=false;$('evolution-confirm').textContent='이 모습으로 진화';});$('evolution-choices').append(button);}
 }catch(error){$('evolution-message').textContent=error.message;}
 $('evolution-confirm').addEventListener('click',()=>{if(busy||!selected)return;if(done){done=false;selected=null;reveal.reset();$('evolution-phase').textContent='가능성을 골라 봐.';$('evolution-stage-name').textContent='아직 쓰이지 않은 다음 이야기.';$('evolution-stage-note').textContent='두 진화형 모두 원본 그림에서 시작해.';$('evolution-message').textContent='다른 성장 방향도 골라 봐.';document.querySelectorAll('.evolution-choice').forEach(b=>{b.disabled=false;b.setAttribute('aria-pressed','false');});$('evolution-confirm').disabled=true;$('evolution-confirm').textContent='진화형을 선택해 줘';return;}busy=true;$('evolution-confirm').disabled=true;document.querySelectorAll('.evolution-choice').forEach(b=>b.disabled=true);$('evolution-phase').textContent='진화 중…';$('evolution-message').textContent='네가 그린 선에, 새로운 힘이 깃들고 있어…';reveal.play(selected.image);});
})();
